sed -i 's/Text("✓ You claimed this task", color = CyanDeep, fontWeight = FontWeight.Medium)/Column {\n                        Text("✓ You claimed this task", color = CyanDeep, fontWeight = FontWeight.Medium)\n                        Spacer(Modifier.height(16.dp))\n                        var completing by remember { mutableStateOf(false) }\n                        Button(\n                            onClick = {\n                                completing = true\n                                scope.launch {\n                                    try {\n                                        val req = okhttp3.RequestBody.create(okhttp3.MultipartBody.FORM, "complete")\n                                        ApiClient.api.completeTask(taskId, req, null)\n                                    } catch (_: Exception) {}\n                                    try { val r = ApiClient.api.getTask(taskId); if(r.isSuccessful) task = r.body() } catch (_: Exception) {}\n                                    completing = false\n                                }\n                            },\n                            modifier = Modifier.fillMaxWidth().height(52.dp),\n                            shape = RoundedCornerShape(26.dp),\n                            enabled = !completing,\n                            colors = ButtonDefaults.buttonColors(containerColor = CyanDeep)\n                        ) {\n                            if (completing) CircularProgressIndicator(Modifier.size(20.dp), color = MaterialTheme.colorScheme.onPrimary, strokeWidth = 2.dp)\n                            else Text("Mark as Completed (Upload Proof)", fontWeight = FontWeight.SemiBold)\n                        }\n                    }/' app/src/main/java/com/strangerhelp/app/ui/screens/tasks/TaskDetailScreen.kt
